def by_id(i: str) -> dict:
    return next(e for e in EVIDENCE if e["id"] == i)


def refs(*ids: str) -> str:
    """Kurzverweis für Hinweistexte, z. B. '[Q6, Q4]'."""
    return "[" + ", ".join(ids) + "]"
